const main=document.querySelector('#main');
const themeDescriptions={research:'冷静 · 精确 · 好奇',minimal:'留白 · 秩序 · 思辨',future:'前沿 · 交互 · 探索'};
function setTheme(theme){if(!themeDescriptions[theme])theme='research';document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)));document.querySelector('.theme-description').textContent=themeDescriptions[theme];document.querySelector('meta[name="theme-color"]').content={research:'#10130f',minimal:'#f8f9fb',future:'#090e1b'}[theme];try{localStorage.setItem('personal-design-theme',theme)}catch{}}
let initialTheme='research';try{initialTheme=localStorage.getItem('personal-design-theme')||'research'}catch{}setTheme(initialTheme);document.querySelectorAll('[data-theme-choice]').forEach(button=>button.addEventListener('click',()=>setTheme(button.dataset.themeChoice)));
const arrow='<span class="round-arrow" aria-hidden="true">↗</span>';
const thoughtHeadline='世界并不确定。<br>思考可以更清晰。';
const graphMarkup=`<svg class="chart" viewBox="0 0 400 170" role="img" aria-label="正态分布示意：增加观察后，后验分布逐渐收窄"><defs><linearGradient id="curve-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c6f38a" stop-opacity=".28"/><stop offset="1" stop-color="#c6f38a" stop-opacity="0"/></linearGradient></defs><path d="M12 145H388" fill="none" stroke="#48533e"/><path d="M106 141v8M200 141v8M294 141v8" stroke="#48533e"/><path class="prior-path" fill="none" stroke="#7c8a6f" stroke-dasharray="4 5" stroke-width="1.5"/><path class="area-path" fill="url(#curve-fill)"/><path class="posterior-path" fill="none" stroke="#c6f38a" stroke-width="2.5"/><text x="106" y="163" fill="#8c9b7f" font-family="monospace" font-size="10" text-anchor="middle">−2</text><text x="200" y="163" fill="#8c9b7f" font-family="monospace" font-size="10" text-anchor="middle">0</text><text x="294" y="163" fill="#8c9b7f" font-family="monospace" font-size="10" text-anchor="middle">2</text></svg>`;
function controls(){return `<div class="graph-footer"><div class="chart-legend"><span>先验</span><span>后验</span></div><div class="evidence-controls"><button class="evidence-reset" aria-label="重置概率实验" title="重置">↺</button><button class="evidence-add">＋ 一条证据</button></div></div><div class="graph-caption"><span class="sample-count" aria-live="polite">OBSERVATIONS / 03</span><span>P(H | D) ∝ P(D | H) P(H)</span></div>`}
function home(){return `<div class="intro-line"><span class="eyebrow">01 / A MIND IN PROGRESS</span><span>保持好奇，持续更新。<span aria-hidden="true"> ↙</span></span></div><div class="bento-grid page-enter">
<section class="card hero"><div class="hero-top"><span class="eyebrow">LOGIC · MATHEMATICS · STATISTICS</span><span class="micro-tag">HELLO, WORLD</span></div><h1>从复杂中，<br>看见<span>结构。</span></h1><p class="hero-description">我关注逻辑、数学与统计，<br>也在探索量化与 AI 的更多可能。</p><div class="hero-bottom"><div class="hero-name">你的名字<small>一句话介绍 · 待填写</small></div><a class="text-link" href="#/background">进一步认识我 ${arrow}</a></div></section>
<section class="card probability"><div class="card-heading"><span class="eyebrow">A SMALL THOUGHT EXPERIMENT</span><span class="small-tag">可交互</span></div><h2 class="graph-title">多一点证据，<br><em>少一点不确定。</em></h2>${graphMarkup}${controls()}</section>
<section class="card skills" aria-label="核心强项"><a class="skill" href="#/strengths"><span class="skill-symbol" aria-hidden="true">⊢</span><div><h2>逻辑推演</h2><p>REASON FROM FIRST PRINCIPLES</p></div><span class="skill-arrow" aria-hidden="true">↗</span></a><a class="skill" href="#/strengths"><span class="skill-symbol" aria-hidden="true">∫</span><div><h2>数学建模</h2><p>FIND THE UNDERLYING STRUCTURE</p></div><span class="skill-arrow" aria-hidden="true">↗</span></a><a class="skill" href="#/strengths"><span class="skill-symbol" aria-hidden="true">σ</span><div><h2>统计推断</h2><p>MAKE SENSE OF UNCERTAINTY</p></div><span class="skill-arrow" aria-hidden="true">↗</span></a></section>
<a class="card thoughts card-link" href="#/thoughts"><div class="card-heading"><span class="eyebrow">CURRENTLY ON MY MIND</span><span class="small-tag">示例观点</span></div><h2>${thoughtHeadline}</h2><div class="thoughts-bottom"><p>我的想法、疑问，以及尚未完成的思考。</p>${arrow}</div></a>
<a class="card quant card-link" href="#/quant"><span class="eyebrow">SIGNAL / NOISE</span><h2>关于量化。</h2><p>模型、市场与不确定性。</p><svg class="signal-chart" viewBox="0 0 400 75" aria-hidden="true"><path d="M0 40H400" stroke="#384332" stroke-dasharray="3 6"/><path class="noise-path" fill="none" stroke="#677a54" stroke-width="1"/><path class="signal-path" fill="none" stroke="#c6f38a" stroke-width="2"/></svg><div class="card-bottom"><span class="eyebrow">MODELS ARE A LENS, NOT THE WORLD</span>${arrow}</div></a>
<a class="card background card-link" href="#/background"><span class="eyebrow">THE PERSON BEHIND</span><span class="mini-math" aria-hidden="true">x → f(x)</span><h2 class="lower-title">我的来路。</h2><p class="lower-copy">背景、经历，以及塑造我的事。</p><div class="card-bottom"><span class="eyebrow">BACKGROUND & EXPERIENCE</span>${arrow}</div></a>
<a class="card philosophy card-link" href="#/philosophy"><span class="eyebrow">WAYS OF SEEING</span><span class="mini-math" aria-hidden="true">∴ &nbsp; ?</span><h2 class="lower-title">思考的底层。</h2><p class="lower-copy">我如何理解知识、选择与世界。</p><div class="card-bottom"><span class="eyebrow">PHILOSOPHY & BELIEFS</span>${arrow}</div></a>
<a class="card lab card-link" href="#/lab"><span class="eyebrow">WHERE IDEAS BECOME REAL</span><span class="lab-symbol" aria-hidden="true">[ ↗ ]</span><h2 class="lower-title">AI 实验室。</h2><p class="lower-copy">把好奇心，变成可以运行的东西。</p><div class="card-bottom"><span class="eyebrow">EXPERIMENTS & CREATIONS</span>${arrow}</div></a>
<section class="card social-row"><div class="social-heading">在别处找到我<span>让对话继续。</span></div><div class="social-links"><button data-social="LinkedIn">LinkedIn <span>↗</span></button><button data-social="GitHub">GitHub <span>↗</span></button><button data-social="Email">Email <span>↗</span></button></div></section></div>`}
const pages={
background:{number:'02',eyebrow:'THE PERSON BEHIND THE QUESTIONS',title:'我的来路。',subtitle:'经历是一条路径。好奇心决定方向。',intro:'在这里，更深入地认识我：从哪里出发，走过哪些阶段，又被哪些问题吸引。',sections:[['01 / EDUCATION','教育与背景','学校、专业与学习路径。','你的教育背景待填写'],['02 / EXPERIENCE','做过什么','工作、研究，以及值得记下的经历。','你的经历待填写'],['03 / CURIOSITY','正在走向哪里','当前关注的方向，与接下来想解决的问题。','你的研究兴趣待填写']],related:[['strengths','我擅长什么'],['philosophy','我的哲学观']]},
strengths:{number:'03',eyebrow:'A TOOLKIT FOR COMPLEXITY',title:'思考的工具箱。',subtitle:'抽象出结构，再回到现实。',intro:'首页里的三个关键词，在这里展开。每一种能力，都可以有自己的方法、边界与应用领域。',sections:[['⊢ / LOGIC','逻辑推演','概念、前提与结论之间，如何建立清晰的连接。','你的方法与擅长领域待填写'],['∫ / MATHEMATICS','数学建模','从复杂问题中提取结构，用模型表达关键关系。','你的数学背景与方向待填写'],['σ / STATISTICS','统计推断','理解数据、噪声与不确定性，形成有依据的判断。','你的统计方法与经验待填写']],wide:['实践与成果','你做过的工作、研究或项目，会在这里展开。可以只写最重要的几件事。'],related:[['background','背景与经历'],['quant','我对量化的看法']]},
thoughts:{number:'04',eyebrow:'NOTES FROM AN UNFINISHED MIND',title:'一些正在生长的想法。',subtitle:'世界并不确定。思考可以更清晰。',intro:'这里留给当下的想法：一个问题，一段观察，或一个仍在变化的判断。',sections:[['01 / QUESTION','最近在想什么','一个让你持续好奇、暂时还没有答案的问题。','第一条想法待填写'],['02 / OBSERVATION','最近看到了什么','一件改变了你看问题方式的事。','第二条想法待填写'],['03 / REVISION','最近改变了什么','一个你正在更新的判断，和促使改变的理由。','第三条想法待填写']],related:[['philosophy','更深的哲学观'],['quant','关于量化']]},
philosophy:{number:'05',eyebrow:'BEYOND THE EQUATIONS',title:'思考的底层。',subtitle:'从「如何知道」，到「如何选择」。',intro:'我对世界的理解、做选择的原则，以及那些不会很快得到答案的问题。',sections:[['01 / KNOWLEDGE','我如何理解知识','什么构成证据？我们在什么条件下说自己知道？','你的认识论观点待填写'],['02 / CHOICE','我如何做选择','如何在不确定中权衡，又如何理解理性与价值。','你的判断原则待填写'],['03 / MEANING','我如何理解意义','什么值得投入时间，什么值得长期坚持。','你的价值观待填写']],wide:['仍然开放的问题','为分歧、修正和新的理解，留一个位置。'],related:[['thoughts','当前想法'],['background','认识我']]},
quant:{number:'06',eyebrow:'BETWEEN SIGNAL AND NOISE',title:'我眼中的量化。',subtitle:'模型是一种视角。市场是更复杂的现实。',intro:'这里留给我对量化研究的看法：如何提问、如何验证，以及如何理解模型的边界。',sections:[['01 / RESEARCH','如何提出问题','我感兴趣的研究方向，以及什么样的问题值得研究。','你的量化观点待填写'],['02 / EVIDENCE','如何检验想法','关于数据、假设、验证与不确定性的思考。','你的研究方法待填写'],['03 / LIMITS','如何理解边界','模型的适用范围、风险，以及面对变化的方式。','你的方法论与边界待填写']],wide:['研究笔记','之后可以在这里放入你的完整观点、图表或研究记录。当前图形仅用于设计示意。'],related:[['strengths','数学与统计背景'],['lab','AI 实验室']]}
};
function detail(route){const p=pages[route];return `<div class="page-enter"><div class="detail-top"><a class="back-link" href="#/">← 返回概览</a><span class="eyebrow">${p.number} / PERSONAL INDEX</span></div><header class="detail-hero"><span class="eyebrow">${p.eyebrow}</span><span class="small-tag">示意文案</span><h1>${p.title}</h1><p>${p.subtitle}</p><div class="draft-note">${p.intro}</div></header><div class="detail-grid">${p.sections.map(s=>`<section class="card detail-card"><span class="detail-num">${s[0]}</span><h2>${s[1]}</h2><p>${s[2]}</p><div class="empty-project"><span class="small-tag">待填写</span><p>${s[3]}</p></div></section>`).join('')}${p.wide?`<section class="card detail-wide"><span class="eyebrow">ROOM FOR MORE</span><h2>${p.wide[0]}</h2><p>${p.wide[1]}</p></section>`:''}</div><nav class="detail-related" aria-label="继续探索">${p.related.map(r=>`<a href="#/${r[0]}">${r[1]} ↗</a>`).join('')}</nav></div>`}
function lab(){return `<div class="page-enter"><div class="detail-top"><a class="back-link" href="#/">← 返回概览</a><span class="eyebrow">07 / PERSONAL INDEX</span></div><header class="detail-hero"><span class="eyebrow">IDEAS, MADE TANGIBLE</span><span class="small-tag">设计预览</span><h1>好奇心的实验场。</h1><p>从一个想法，到一个可以运行的东西。</p><div class="draft-note">你的 AI 作品将放在这里。先试试为这个网站制作的概率小实验。</div></header><section class="card full-experiment"><div><span class="eyebrow">00 / AN INTERACTIVE SKETCH</span><h2>证据如何改变判断？</h2><p class="experiment-explanation">点击「一条证据」，观察先验如何更新为后验。这个小实验用正态模型，展示判断随观察增加而收窄的过程。</p><div class="formula">P(H | D) ∝ P(D | H) · P(H)</div><p class="experiment-explanation">演示假设：先验 N(0, 1)，每次独立观察值固定为 0.65，观测标准差 0.8。为方便比较，曲线使用相同的纵轴尺度；它是一个受控示例。</p><span class="small-tag">本站互动示例 · 非个人作品履历</span></div><div>${graphMarkup}${controls()}</div></section><div class="detail-grid lab-projects"><section class="card detail-card"><span class="detail-num">01 / AI PROJECT</span><h2>第一件 AI 作品</h2><p>作品名称、解决的问题、你的角色，以及可体验的链接。</p><div class="empty-project"><span class="small-tag">作品待添加</span></div></section><section class="card detail-card"><span class="detail-num">02 / AI PROJECT</span><h2>第二件 AI 作品</h2><p>另一个有代表性的尝试。完成品和有意思的实验都可以。</p><div class="empty-project"><span class="small-tag">作品待添加</span></div></section><section class="card detail-card"><span class="detail-num">03 / OPEN QUESTION</span><h2>下一个想法</h2><p>还没有做出来，但已经值得开始思考的事情。</p><div class="empty-project"><span class="small-tag">想法待填写</span></div></section></div><nav class="detail-related" aria-label="继续探索"><a href="#/thoughts">当前想法 ↗</a><a href="#/quant">关于量化 ↗</a></nav></div>`}
function render(){const requested=location.hash.replace(/^#\/?/,'')||'home';const route=requested==='lab'||pages[requested]?requested:'home';main.innerHTML=route==='home'?home():route==='lab'?lab():detail(route);document.title=(route==='home'?'你的名字':route==='lab'?'AI 实验室':pages[route].title)+' — Signal & Structure';document.querySelectorAll('[data-nav]').forEach(a=>{const active=route==='home'?'home':route==='lab'?'lab':['thoughts','philosophy','quant'].includes(route)?'thoughts':null;if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});wire();}
function wire(){let count=3;const curve=(mu,sigma)=>Array.from({length:241},(_,i)=>{const x=-4+i/30;return [(12+(x+4)*47).toFixed(2),(145-80*Math.exp(-.5*((x-mu)/sigma)**2)/(sigma*Math.sqrt(2*Math.PI))).toFixed(2)]});const path=points=>'M'+points.map(p=>p.join(' ')).join('L');function redraw(){const variance=.64/(.64+count);const posterior=curve(count*.65/(.64+count),Math.sqrt(variance));document.querySelectorAll('.prior-path').forEach(e=>e.setAttribute('d',path(curve(0,1))));document.querySelectorAll('.posterior-path').forEach(e=>e.setAttribute('d',path(posterior)));document.querySelectorAll('.area-path').forEach(e=>e.setAttribute('d',path(posterior)+'L388 145L12 145Z'));document.querySelectorAll('.sample-count').forEach(e=>e.textContent='OBSERVATIONS / '+String(count).padStart(2,'0'));document.querySelectorAll('.evidence-add').forEach(e=>{e.disabled=count>=10;e.textContent=count>=10?'已观察 10 次':'＋ 一条证据'});}document.querySelectorAll('.evidence-add').forEach(e=>e.addEventListener('click',()=>{count=Math.min(count+1,10);redraw()}));document.querySelectorAll('.evidence-reset').forEach(e=>e.addEventListener('click',()=>{count=0;redraw()}));redraw();const points=Array.from({length:101},(_,i)=>{let x=i*4,y=40-11*Math.sin(i*.085)-5*Math.cos(i*.14);return {x,y,noise:y+10*Math.sin(i*2.31)+6*Math.cos(i*3.65)}});document.querySelectorAll('.signal-path').forEach(e=>e.setAttribute('d','M'+points.map(p=>p.x+','+p.y.toFixed(2)).join('L')));document.querySelectorAll('.noise-path').forEach(e=>e.setAttribute('d','M'+points.map(p=>p.x+','+p.noise.toFixed(2)).join('L')));document.querySelectorAll('[data-social]').forEach(e=>e.addEventListener('click',()=>{document.querySelector('#link-title').textContent=e.dataset.social;document.querySelector('#link-dialog').showModal()}));}
document.querySelector('#year').textContent=new Date().getFullYear();window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return}render();window.scrollTo(0,0);main.focus({preventScroll:true})});render();
